def is_Sub_Array(main_list, sub_list):
    # Check if the sub_list is empty
    if not sub_list:
        return True
    # Check if the main_list is empty
    if not main_list:
        return False
    # Iterate through the main_list
    for i in range(len(main_list)):
        # Check if the current element matches the first element of the sub_list
        if main_list[i] == sub_list[0]:
            # Check if the remaining elements of the sub_list match the remaining elements of the main_list
            if main_list[i:i+len(sub_list)] == sub_list:
                return True
    # If no match is found, return False
    return False
